<template x-if="task.result_data">
<div class="result-summary">
    <template x-if="task.type === 'demo_delay'"><dl class="details"><dt>Запрошено</dt><dd x-text="task.result_data.requested_seconds + ' с'"></dd><dt>Фактически прошло</dt><dd x-text="task.result_data.actual_seconds + ' с'"></dd></dl></template>
    <template x-if="task.type === 'text_analysis'"><div><dl class="details"><dt>Символов</dt><dd x-text="task.result_data.characters"></dd><dt>Слов</dt><dd x-text="task.result_data.words"></dd><dt>Строк</dt><dd x-text="task.result_data.lines"></dd><dt>Уникальных слов</dt><dd x-text="task.result_data.unique_words"></dd></dl><h3>Частые слова</h3><table><thead><tr><th>Слово</th><th>Количество</th></tr></thead><tbody><template x-for="word in task.result_data.top_words" :key="word.word"><tr><td x-text="word.word"></td><td x-text="word.count"></td></tr></template></tbody></table></div></template>
    <template x-if="task.type === 'csv_analysis'"><div><dl class="details"><dt>Записей</dt><dd x-text="task.result_data.rows"></dd><dt>Столбцов</dt><dd x-text="task.result_data.column_count"></dd><dt>Пустых значений</dt><dd x-text="task.result_data.empty_values"></dd></dl><div class="table-scroll"><table><thead><tr><th>Столбец</th><th>Пусто</th><th>Min</th><th>Max</th><th>Сумма</th><th>Среднее</th></tr></thead><tbody><template x-for="column in task.result_data.columns" :key="column.name"><tr><td x-text="column.name"></td><td x-text="column.empty"></td><td x-text="column.min ?? '—'"></td><td x-text="column.max ?? '—'"></td><td x-text="column.sum ?? '—'"></td><td x-text="column.avg ?? '—'"></td></tr></template></tbody></table></div><p class="help">Статистика вычисляется по непустым значениям полностью числовых столбцов.</p></div></template>
    <details class="section-gap"><summary>JSON результата</summary><pre x-text="JSON.stringify(task.result_data, null, 2)"></pre></details>
</div>
</template>
